using System;
using System.Collections.Generic;
using UnityEngine;

namespace RTXMnesia.Ui
{
    public enum HplFontAlign { Left, Right, Center }

    /// <summary>
    /// A game bitmap font (AngelCode .fnt, cSDLFontData::CreateFromBitmapFile): glyph metrics divided by the line height,
    /// so a font size is the row height on HPL2's 800×600 HUD; the pages of the font are stacked into one atlas.
    /// Layout as iFontData::GetLength / GetWordWrapRows and cGuiSet::DrawTextFromCharArry. Generated by
    /// FontConverter into Assets/AmnesiaImported/Fonts (game data, never in git).
    /// </summary>
    public class HplFont : ScriptableObject
    {
        [Serializable]
        public struct Glyph
        {
            public int id;
            [Tooltip("Atlas UV rect (Unity, v up).")]
            public Rect uv;
            [Tooltip("Offset and size in line heights (y down).")]
            public Vector2 offset, size;
            public float advance;
        }

        public string file;
        public Texture2D atlas;
        [Tooltip("lineHeight of the .fnt in pixels.")]
        public float height;
        [Tooltip("Largest glyph id (mlLastChar; the first is 0).")]
        public int lastChar;
        public List<Glyph> glyphs = new();

        Dictionary<int, Glyph> _map;

        public bool TryGetGlyph(char c, out Glyph glyph)
        {
            if (_map == null)
            {
                _map = new Dictionary<int, Glyph>(glyphs.Count);
                foreach (var g in glyphs) _map[g.id] = g;
            }
            glyph = default;
            return c <= lastChar && _map.TryGetValue(c, out glyph);
        }

        /// <summary>iFontData::GetLength: the sum of the advances.</summary>
        public float GetLength(Vector2 size, string text)
        {
            float length = 0f;
            foreach (char c in text)
                if (TryGetGlyph(c, out var g)) length += g.advance * size.x;
            return length;
        }

        /// <summary>
        /// iFontData::GetWordWrapRows: breaks at spaces (and '\n') where the text since the row start gets longer than
        /// the length; the break space is dropped. (The CJK full-width punctuation rule is kept.)
        /// </summary>
        public List<string> GetWordWrapRows(float length, Vector2 size, string text)
        {
            var rows = new List<string>();
            var breaks = new List<(int pos, bool incr)>();
            int count = 0, firstLetter = 0, lastSpace = 0, pos;
            for (pos = 0; pos < text.Length; pos++)
            {
                char c = text[pos];
                bool fullwidth = IsChineseFullwidthChar(c);
                if (c != ' ' && c != '\n' && !fullwidth) continue;
                float textLength = GetLength(size, text.Substring(firstLetter, pos - firstLetter));
                bool nothing = true;
                if (textLength > length && !fullwidth)
                {
                    count++;
                    breaks.Add((lastSpace, true));
                    firstLetter = lastSpace + 1;
                    lastSpace = pos;
                    nothing = false;
                }
                else if (textLength > length && fullwidth)
                {
                    breaks.Add((lastSpace + 1, false));
                    firstLetter = lastSpace + 1;
                    lastSpace = pos;
                    count++;
                    nothing = false;
                }
                if (c == '\n')
                {
                    lastSpace = pos;
                    firstLetter = lastSpace + 1;
                    breaks.Add((lastSpace, true));
                    count++;
                    nothing = false;
                }
                if (nothing) lastSpace = pos;
            }
            if (GetLength(size, text.Substring(Math.Min(firstLetter, text.Length))) > length)
            {
                count++;
                breaks.Add((lastSpace, true));
            }

            if (count == 0)
            {
                rows.Add(text);
                return rows;
            }
            firstLetter = 0;
            foreach (var (breakPos, incr) in breaks)
            {
                rows.Add(Substring(text, firstLetter, breakPos - firstLetter));
                firstLetter = breakPos;
                if (incr) firstLetter++;
            }
            rows.Add(firstLetter < text.Length ? text.Substring(firstLetter) : "");
            return rows;
        }

        // std::wstring::substr: a count past the end is clamped (a negative one, as size_t, too).
        static string Substring(string s, int start, int count)
        {
            if (start >= s.Length) return "";
            if (count < 0 || start + count > s.Length) count = s.Length - start;
            return s.Substring(start, count);
        }

        static bool IsChineseFullwidthChar(char c) => c == 12290 || c == 65292 || c == 65311 || c == 65281;
    }
}
